import re, glob

txt = {}
for p in sorted(glob.glob('draft/*.md')) + sorted(glob.glob('figures/*.md')):
    txt[p] = open(p).read()

bad = ['TODO', 'TBD', 'placeholder', '[insert', 'XXX', '—', 'draftsperson', 'revised', 'version 2']
for p, t in txt.items():
    for b in bad:
        if b.lower() in t.lower():
            print('MARKER', p, b)

tbl = dict(re.findall(r'^\|\s*(\d+)\s*\|\s*([^|]+?)\s*\|$', txt['draft/numerals.md'], re.M))
spec = set()
for p in sorted(glob.glob('draft/0*.md')):
    spec |= set(re.findall(r'\b(\d{2,3})\b', txt[p]))
print('spec numerals not in table:', sorted(n for n in spec if n not in tbl))

figs = {}
for p in sorted(glob.glob('figures/*.md')):
    body, sec = txt[p].split('## Numerals shown on this figure')
    figs[p] = re.findall(r'^-\s*(\d+):', sec, re.M)
    used = set(re.findall(r'\b(\d{2,3})\b', body))
    print(p, len(figs[p]), 'listed; chars', len(txt[p]),
          'body numerals not listed:', sorted(used - set(figs[p])))

allfig = set(n for v in figs.values() for n in v)
print('table numerals missing from all figures:', sorted(set(tbl) - allfig))
print('figure numerals not in table:', sorted(allfig - set(tbl)))

